<?php require_once '../config/app.php';require_role('admin');$title='Klientët';if(isset($_GET['delete'])){stmt($conn,"DELETE FROM users WHERE id=? AND role='customer'",'i',[(int)$_GET['delete']]);flash('Klienti u fshi.');redirect('customers.php');}$rows=$conn->query("SELECT u.id,u.full_name,u.email,u.created_at,COUNT(DISTINCT v.id) vehicles,COUNT(DISTINCT a.id) appointments FROM users u LEFT JOIN vehicles v ON v.user_id=u.id LEFT JOIN appointments a ON a.user_id=u.id WHERE u.role='customer' GROUP BY u.id ORDER BY u.created_at DESC");include '../includes/admin_header.php';?><div class="toolbar"><input class="search" placeholder="Kërko klientë..." data-search="#customers"><span class="muted">Llogaritë e klientëve</span></div><div class="table-wrap"><table class="data-table" id="customers"><thead><tr><th>Klienti</th><th>Emaili</th><th>Automjetet</th><th>Terminet</th><th>Regjistruar më</th><th>Veprimi</th></tr></thead><tbody><?php if(!$rows->num_rows):?><tr><td colspan="6" class="empty">Ende nuk ka klientë të regjistruar.</td></tr><?php else:while($r=$rows->fetch_assoc()):?><tr><td><b><?=e($r['full_name'])?></b></td><td><?=e($r['email'])?></td><td><?=e($r['vehicles'])?></td><td><?=e($r['appointments'])?></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td><td><a class="btn btn-danger btn-sm" data-confirm="Të fshihen ky klient dhe të dhënat e lidhura me të?" href="?delete=<?=$r['id']?>">Fshi</a></td></tr><?php endwhile;endif;?></tbody></table></div><?php include '../includes/footer.php';?>
